// <auto-generated />
using UnityEngine;
using System.Collections.Generic;

namespace Spinnenspiel
{
    public static class JunglePlantFactory
    {
        /// <summary>
        /// Erstellt eine Riesenblatt-Pflanze (Monstera-artig) deterministisch aus seed.
        /// Reine Laufzeit-Mesh-Fabrik, kein Editor-Code.
        /// </summary>
        public static Mesh GiantLeafPlant(int seed)
        {
            var rng = new System.Random(seed);
            float R(float a, float b) => a + (float)rng.NextDouble() * (b - a);

            int nBlatter = rng.Next(3, 8); // 3–7 Blätter
            List<Vector3> allVertices = new List<Vector3>();
            List<int> allTriangles = new List<int>();
            List<Vector2> allUVs = new List<Vector2>();
            List<Vector3> allNormals = new List<Vector3>();

            for (int i = 0; i < nBlatter; i++)
            {
                float stielRadius = R(0.008f, 0.015f);
                float stielLaenge = R(0.3f, 0.9f);
                float azimut = rng.Next(0, 360);
                float neigungVonSenkrechten = R(20f, 45f);
                float stielDirX = Mathf.Cos(azimut * Mathf.Deg2Rad) * Mathf.Sin(neigungVonSenkrechten * Mathf.Deg2Rad);
                float stielDirY = Mathf.Cos(neigungVonSenkrechten * Mathf.Deg2Rad);
                float stielDirZ = Mathf.Sin(azimut * Mathf.Deg2Rad) * Mathf.Sin(neigungVonSenkrechten * Mathf.Deg2Rad);

                for (int side = 0; side < 6; side++)
                {
                    float sideAngle = (side + 0.5f) * 60f * Mathf.Deg2Rad;
                    Vector3 sideDir = new Vector3(
                        Mathf.Cos(sideAngle),
                        0,
                        Mathf.Sin(sideAngle)
                    );
                    Vector3 sideNormal = new Vector3(
                        sideDir.x * stielDirX + sideDir.z * stielDirY,
                        sideDir.y * stielDirX - sideDir.x * stielDirY,
                        sideDir.z * stielDirY + sideDir.y * stielDirX
                    );

                    Vector3 bottomPos = sideDir * stielRadius;
                    Vector3 topPos = sideDir * stielRadius * stielLaenge;

                    allVertices.Add(bottomPos);
                    allNormals.Add(sideNormal.normalized);
                    allUVs.Add(new Vector2(0, 0));

                    allVertices.Add(topPos);
                    allNormals.Add(sideNormal.normalized);
                    allUVs.Add(new Vector2(0, 1));
                }

                for (int tri = 0; tri < 6; tri++)
                {
                    int i1 = tri * 2;
                    int i2 = tri * 2 + 1;
                    int i3 = (tri + 1) * 2;
                    int i4 = (tri + 1) * 2 + 1;

                    allTriangles.Add(i1 + allVertices.Count - 12);
                    allTriangles.Add(i2 + allVertices.Count - 12);
                    allTriangles.Add(i3 + allVertices.Count - 12);
                    allTriangles.Add(i4 + allVertices.Count - 12);
                    allTriangles.Add(i2 + allVertices.Count - 12);
                    allTriangles.Add(i3 + allVertices.Count - 12);
                }

                float blattLaenge = R(0.35f, 1.0f);
                float blattBreite = blattLaenge * R(0.6f, 0.9f);
                float stielEndLae = stielLaenge;
                float azimutBlatt = rng.Next(0, 360);
                float neigungBlatt = R(20f, 45f);
                Vector3 blattFoot = new Vector3(
                    Mathf.Cos(azimutBlatt * Mathf.Deg2Rad) * Mathf.Sin(neigungBlatt * Mathf.Deg2Rad) * stielEndLae,
                    Mathf.Cos(neigungBlatt * Mathf.Deg2Rad) * stielEndLae,
                    Mathf.Sin(azimutBlatt * Mathf.Deg2Rad) * Mathf.Sin(neigungBlatt * Mathf.Deg2Rad) * stielEndLae
                );

                int rasterQuer = 7;
                int rasterLanga = 10;

                for (int r = 0; r < rasterLanga; r++)
                {
                    float tY = (float)r / rasterLanga;
                    float scaleX = (1.0f - tY) * blattLaenge;
                    float scaleY = (1.0f - tY) * blattBreite;

                    for (int c = 0; c < rasterQuer; c++)
                    {
                        float uLocal = (float)c / rasterQuer;
                        float vLocal = (float)r / rasterLanga;

                        float x = uLocal * scaleX;
                        float y = vLocal * scaleY;

                        if (r == rasterLanga - 1)
                        {
                            y -= R(0.1f, 0.25f);
                        }

                        Vector3 leafPos = blattFoot + new Vector3(x, y, 0);
                        Vector3 leafNormal = new Vector3(-blattFoot.x, blattFoot.y, blattFoot.z).normalized;

                        for (int side = 0; side < 6; side++)
                        {
                            float sideAngle = (side + 0.5f) * 60f * Mathf.Deg2Rad;
                            Vector3 sideDir = new Vector3(
                                Mathf.Cos(sideAngle),
                                0,
                                Mathf.Sin(sideAngle)
                            );
                            Vector3 sideNormal = new Vector3(
                                sideDir.x * leafNormal.x + sideDir.z * leafNormal.z,
                                sideDir.y * leafNormal.x - sideDir.x * leafNormal.z,
                                sideDir.z * leafNormal.y + sideDir.y * leafNormal.x
                            );

                            Vector3 leafVert = leafPos + sideDir * y * 0.1f;
                            allVertices.Add(leafVert);
                            allNormals.Add(sideNormal.normalized);
                            allUVs.Add(new Vector2(uLocal, vLocal));
                        }
                    }
                }
            }

            Mesh mesh = new Mesh();
            mesh.name = "GiantLeaf_" + seed;
            if (allVertices.Count > 60000)
            {
                mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
            }
            mesh.SetVertices(allVertices);
            mesh.SetTriangles(allTriangles.ToArray(), 0);
            mesh.SetUVs(0, allUVs.ToArray());
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();

            return mesh;
        }
    }
}
